function GardenIrrigationTimerMaker.init() GardenIrrigationTimerMaker.ironStock=14; GardenIrrigationTimerMaker.bronzeStock=12; GardenIrrigationTimerMaker.woodStock=12; GardenIrrigationTimerMaker.leatherStock=8; GardenIrrigationTimerMaker.silverStock=8; GardenIrrigationTimerMaker.goldStock=6; GardenIrrigationTimerMaker.jewelStock=4; GardenIrrigationTimerMaker.pearlStock=4; GardenIrrigationTimerMaker.productStock={}; GardenIrrigationTimerMaker.buildings={}; GardenIrrigationTimerMaker.maker=nil; GardenIrrigationTimerMaker.activeMaking={}; GardenIrrigationTimerMaker.totalProducts=0; GardenIrrigationTimerMaker.dayTimer=0; print("[GardenIrrigationTimerMaker] Royal Garden Irrigation Timer Maker System initialized (6 products, 4 buildings)") end
function GardenIrrigationTimerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenIrrigationTimerMaker.maker={name=n or ("Časovnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Časovnikar najet: %s (spretnost: %d)",GardenIrrigationTimerMaker.maker.name,s),"success") end; return true end
function GardenIrrigationTimerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenIrrigationTimerMaker.build(id) local ok,e=GardenIrrigationTimerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenIrrigationTimerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenIrrigationTimerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenIrrigationTimerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenIrrigationTimerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenIrrigationTimerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenIrrigationTimerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenIrrigationTimerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenIrrigationTimerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenIrrigationTimerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenIrrigationTimerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenIrrigationTimerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenIrrigationTimerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenIrrigationTimerMaker.buildings==0 then return false,"Potrebna časovna delavnica" end; if not GardenIrrigationTimerMaker.maker then return false,"Potreben casovnikar" end; return true end
function GardenIrrigationTimerMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenIrrigationTimerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenIrrigationTimerMaker.ironStock=GardenIrrigationTimerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenIrrigationTimerMaker.bronzeStock=GardenIrrigationTimerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenIrrigationTimerMaker.woodStock=GardenIrrigationTimerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenIrrigationTimerMaker.leatherStock=GardenIrrigationTimerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenIrrigationTimerMaker.silverStock=GardenIrrigationTimerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenIrrigationTimerMaker.goldStock=GardenIrrigationTimerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenIrrigationTimerMaker.jewelStock=GardenIrrigationTimerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenIrrigationTimerMaker.pearlStock=GardenIrrigationTimerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenIrrigationTimerMaker.maker then t=math.max(1,t-math.floor(GardenIrrigationTimerMaker.maker.skill/13)) end; table.insert(GardenIrrigationTimerMaker.activeMaking,{id="gardenirrigationtimer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenIrrigationTimerMaker.completeMaking(m) local q=1.0+(GardenIrrigationTimerMaker.getQualityBonus()/100); if GardenIrrigationTimerMaker.maker then q=q+(GardenIrrigationTimerMaker.maker.skill/140) end; q=math.min(2.5,q); GardenIrrigationTimerMaker.productStock[m.productType]=(GardenIrrigationTimerMaker.productStock[m.productType] or 0)+m.quantity; GardenIrrigationTimerMaker.totalProducts=GardenIrrigationTimerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenIrrigationTimerMaker.maker then GardenIrrigationTimerMaker.maker.itemsMade=GardenIrrigationTimerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenIrrigationTimerMaker.maker.skill=math.min(100,GardenIrrigationTimerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Časovnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenirrigationtimer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenIrrigationTimerMaker.update(dt) if not _G.state then return end; GardenIrrigationTimerMaker.dayTimer=GardenIrrigationTimerMaker.dayTimer+dt; if GardenIrrigationTimerMaker.dayTimer>=30 then GardenIrrigationTimerMaker.dayTimer=0; for i=#GardenIrrigationTimerMaker.activeMaking,1,-1 do local m=GardenIrrigationTimerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenIrrigationTimerMaker.completeMaking(m); table.remove(GardenIrrigationTimerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenIrrigationTimerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenIrrigationTimerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenIrrigationTimerMaker.getStats() return {ironStock=GardenIrrigationTimerMaker.ironStock,bronzeStock=GardenIrrigationTimerMaker.bronzeStock,woodStock=GardenIrrigationTimerMaker.woodStock,leatherStock=GardenIrrigationTimerMaker.leatherStock,silverStock=GardenIrrigationTimerMaker.silverStock,goldStock=GardenIrrigationTimerMaker.goldStock,jewelStock=GardenIrrigationTimerMaker.jewelStock,pearlStock=GardenIrrigationTimerMaker.pearlStock,productStock=GardenIrrigationTimerMaker.productStock,numBuildings=#GardenIrrigationTimerMaker.buildings,hasMaker=GardenIrrigationTimerMaker.maker~=nil,makerName=GardenIrrigationTimerMaker.maker and GardenIrrigationTimerMaker.maker.name or "—",makerSkill=GardenIrrigationTimerMaker.maker and GardenIrrigationTimerMaker.maker.skill or 0,activeMaking=#GardenIrrigationTimerMaker.activeMaking,totalProducts=GardenIrrigationTimerMaker.totalProducts} end
